(3,'pencegahan','level','Tata air yang baik pada lahan gambut membantu ...','["Mencegah kebakaran dengan menjaga kebasahan gambut", "Mempercepat kebakaran", "Menghilangkan semua pohon", "Menaikkan suhu udara"]',0,'Pengelolaan tata air yang baik menjaga gambut tetap basah.','pencegahan',1,0),
(3,'pencegahan','level','Pernyataan yang tepat tentang gambut yang terjaga kebasahannya adalah ...','["Membantu mencegah kebakaran", "Selalu mudah terbakar", "Tidak berpengaruh pada kebakaran", "Menghasilkan asap lebih banyak"]',0,'Lahan gambut yang terjaga kebasahannya membantu mencegah kebakaran.','pencegahan',1,0),
