(4,'kesehatan','level','ISPA adalah singkatan dari ...','["Infeksi saluran pernapasan akut", "Iritasi saluran pencernaan akut", "Infeksi sendi pada anak", "Imunisasi sekolah pertama anak"]',0,'ISPA adalah infeksi saluran pernapasan akut.','ispa',1,0),
