(5,'darurat','level','Saat petugas memberi arahan evakuasi, warga sebaiknya ...','["Mengikuti arahan petugas dan mendahulukan keselamatan manusia", "Menolak dan mengambil barang dulu", "Berlari ke arah api", "Mengabaikan arahan"]',0,'Ikuti arahan petugas dan dahulukan keselamatan manusia di atas barang.','evakuasi',1,0),
(5,'darurat','level','Analisis yang dimuat Mongabay (2026) menyebut kelompok yang juga lebih rentan adalah ...','["Penyandang disabilitas dan pekerja ruang terbuka", "Hanya atlet profesional", "Hanya penghuni gedung tinggi", "Tidak ada kelompok lain"]',0,'Selain kelompok umum, penyandang disabilitas dan pekerja ruang terbuka juga lebih rentan.','evakuasi',1,0),
(5,'darurat','level','Kelompok yang perlu dilindungi lebih dulu saat asap pekat adalah ...','["Bayi, balita, ibu hamil, lansia, dan penderita penyakit paru, jantung, atau asma", "Hanya orang dewasa sehat", "Hanya yang tinggal jauh dari asap", "Tidak ada kelompok khusus"]',0,'Kelompok rentan perlu mendapat perlindungan lebih dulu.','evakuasi',1,0),
(5,'darurat','level','Saat asap pekat, nenekmu (lansia) ada di rumah. Tindakan yang tepat adalah ...','["Menemaninya tetap di rumah, membantu kebutuhannya, dan ke fasilitas kesehatan bila ada keluhan", "Mengajaknya jalan pagi", "Membuka semua jendela agar sejuk", "Menyuruhnya bekerja di kebun"]',0,'Kelompok rentan sebaiknya tetap di rumah dan segera ke fasilitas kesehatan bila ada keluhan.','evakuasi',1,0),
(5,'darurat','level','Api membesar di lahan dekat desa. Urutan tindakan yang tepat adalah ...','["Lapor ke 117, BPBD, atau pemadam dengan menyebut lokasi, jauhi asap, ikuti petugas", "Padamkan sendiri sampai habis", "Unggah foto dulu baru melapor", "Tunggu sampai ada orang lain yang melapor"]',0,'Segera laporkan dengan lokasi jelas, jauhi asap, dan ikuti arahan petugas.','darurat',1,0),
(5,'darurat','level','Dalam keadaan darurat evakuasi, yang harus didahulukan adalah ...','["Keselamatan jiwa manusia", "Barang elektronik", "Perabot rumah", "Hasil kebun"]',0,'Keselamatan jiwa lebih penting daripada barang.','evakuasi',1,0),
(5,'darurat','level','Kontak dengan label "belum diverifikasi" di Pusat Bantuan berarti ...','["Nomornya perlu dikonfirmasi ke instansi terkait", "Nomornya pasti salah", "Nomornya sudah dijamin resmi", "Nomornya tidak boleh dihubungi dalam keadaan apa pun"]',0,'Kontak itu diberikan pemilik proyek dan belum dikonfirmasi instansi.','darurat',1,0),
(5,'darurat','level','Tetangga lansia tidak boleh keluar rumah saat asap pekat. Bantuan yang tepat adalah ...','["Membantu memenuhi kebutuhan harian mendesaknya", "Mengajaknya berkumpul di lapangan", "Membiarkannya mengurus semuanya sendiri", "Menjauhi rumahnya"]',0,'Warga yang tidak termasuk kelompok rentan dapat membantu memenuhi kebutuhan harian yang mendesak.','evakuasi',1,0);
